select sub.slug, lvl.level::text as level, t.slug as topic, m.id, m.material_type, length(m.content) as len, left(m.title,60) as title, left(replace(m.content,chr(10),' '),90) as head from public.study_materials m join public.topics t on t.id=m.topic_id join public.subject_levels lvl on lvl.id=t.subject_level_id join public.subjects sub on sub.id=lvl.subject_id where (m.material_type in ('notes','note') and length(m.content)<1000) or length(m.content)<200 order by sub.slug, lvl.level, t.slug;
